  ["creature.drow-commander.tftyp2014"]={title="Drow Commander",subtitle="Criatura - TftYP - 2014",body="Pagina: 209\n\n=== ESTATISTICAS ===\n\nPV: 110 (11d8 + 22)"},
  ["creature.drow-commoner.oota2014"]={title="Drow Commoner",subtitle="Criatura - OotA - 2014",body="Pagina: 194\n\n=== ESTATISTICAS ==="},
